const TEST_PRIVATE_KEY_B64 = '';
const TEST_PUBLIC_KEY_B64 = '';

// Set env var BEFORE importing the module
process.env.INTERNAL_JWT_PRIVATE_KEY_B64 = TEST_PRIVATE_KEY_B64;
process.env.API_GATEWAY_PUBLIC_KEY_B64 = TEST_PUBLIC_KEY_B64;

import { generateInternalToken, verifyInternalToken } from '@aegis/auth';
import * as jwt from 'jsonwebtoken';

describe('RS256 Internal Token', () => {
  const validPayload = { sub: 'gateway', userId: 'test-user', role: 'user' };
  const validAudience = 'aegis-internal';

  it('generates a valid RS256 token and verifies it with the public key', () => {
    const token = generateInternalToken(validPayload, validAudience);
    const decoded = verifyInternalToken(token, validAudience) as any;
    expect(decoded.sub).toBe(validPayload.sub);
    expect(decoded.iss).toBe('aegis-gateway');
    expect(decoded.aud).toBe(validAudience);
  });

  it('rejects a token signed with HS256 (algorithm confusion attack prevention)', () => {
    // Forge a token with HS256 using the public key as the HMAC secret
    const PUBLIC_KEY = Buffer.from(TEST_PUBLIC_KEY_B64, 'base64').toString('utf-8');
    const forgedToken = jwt.sign({ sub: 'attacker' }, PUBLIC_KEY, { 
      algorithm: 'HS256',
      issuer: 'aegis-gateway',
      audience: validAudience
    });
    expect(() => verifyInternalToken(forgedToken, validAudience)).toThrow('Invalid internal token');
  });

  it('rejects an expired token', () => {
    const PRIVATE_KEY = Buffer.from(TEST_PRIVATE_KEY_B64, 'base64').toString('utf-8');
    const expiredToken = jwt.sign({ sub: 'gateway' }, PRIVATE_KEY, {
      algorithm: 'RS256',
      expiresIn: '-10s',
      issuer: 'aegis-gateway',
      audience: validAudience,
    });
    expect(() => verifyInternalToken(expiredToken, validAudience)).toThrow('Invalid internal token');
  });

  describe('Direct Service Access (Missing token)', () => {
    it('should reject the missing token', () => {
      expect(() => verifyInternalToken('', validAudience)).toThrow('Invalid internal token');
    });

    it('should throw when the token in malformed', () => {
      expect(() => verifyInternalToken('malformed-token', validAudience)).toThrow('Invalid internal token');
    });
  });

  describe('Token use on wrong audience', () => {
    const token = generateInternalToken(validPayload, validAudience);
    it('should reject the token with wrong audience', () => {
      expect(() => verifyInternalToken(token, 'wrong-audience')).toThrow('Invalid internal token');
    });
  });

  describe('Token use on wrong issuer', () => {
    it('should reject the token with wrong issuer', () => {
      const PRIVATE_KEY = Buffer.from(TEST_PRIVATE_KEY_B64, 'base64').toString('utf-8');
      const token = jwt.sign(validPayload, PRIVATE_KEY, {
        algorithm: 'RS256',
        issuer: 'wrong-issuer',
        audience: validAudience,
        expiresIn: '1m',
      });
      expect(() => verifyInternalToken(token, validAudience)).toThrow('Invalid internal token');
    });
  });
});
